mapper.update:
UPDATE wms_stock SET qty = qty + #{qty}, update_time = NOW()
WHERE warehouse_id = #{warehouseId} AND location_id = #{locationId}
  AND material_id = #{materialId} AND batch_no = #{batchNo}

UPDATE wms_stock SET qty = qty - #{qty}, update_time = NOW()
WHERE warehouse_id = #{warehouseId} AND location_id = #{locationId}
  AND material_id = #{materialId} AND batch_no = #{batchNo}
  AND qty - frozen_qty >= #{qty}

UPDATE wms_stock SET frozen_qty = frozen_qty + #{qty}, update_time = NOW()
WHERE warehouse_id = #{warehouseId} AND location_id = #{locationId}
  AND material_id = #{materialId} AND batch_no = #{batchNo}
  AND qty - frozen_qty >= #{qty}

UPDATE wms_stock SET frozen_qty = frozen_qty - #{qty}, update_time = NOW()
WHERE warehouse_id = #{warehouseId} AND location_id = #{locationId}
  AND material_id = #{materialId} AND batch_no = #{batchNo}
  AND frozen_qty >= #{qty}

mapper.sql:
SELECT s.id, s.warehouse_id, w.name AS warehouse_name, s.location_id, l.code AS location_code, l.name AS location_name, s.material_id, m.code AS material_code, m.name AS material_name, m.spec, m.unit, m.batch_enabled, m.serial_enabled, s.batch_no, b.production_date, b.expiry_date, s.qty, s.frozen_qty FROM wms_stock s JOIN wms_material m ON m.id = s.material_id JOIN wms_warehouse w ON w.id = s.warehouse_id LEFT JOIN wms_location l ON l.id = s.location_id LEFT JOIN wms_batch b ON b.material_id = s.material_id AND b.batch_no = s.batch_no
s.qty <> 0 AND s.warehouse_id = #{q.warehouseId} AND s.location_id = #{q.locationId} AND s.material_id = #{q.materialId}
AND (m.code LIKE CONCAT('%', #{q.keyword}, '%') OR m.name LIKE CONCAT('%', #{q.keyword}, '%'))
AND s.batch_no LIKE CONCAT('%', #{q.batchNo}, '%') AND m.category = #{q.category}

mapper.select:
SELECT m.id AS material_id, m.code AS material_code, m.name AS material_name, m.spec, m.unit, m.category, m.safety_stock, COALESCE(SUM(s.qty), 0) AS qty, COALESCE(SUM(s.frozen_qty), 0) AS frozen_qty FROM wms_material m LEFT JOIN wms_stock s ON s.material_id = m.id AND s.warehouse_id = #{q.warehouseId}
m.id = #{q.materialId}
AND (m.code LIKE CONCAT('%', #{q.keyword}, '%') OR m.name LIKE CONCAT('%', #{q.keyword}, '%'))
AND m.category = #{q.category}
GROUP BY m.id, m.code, m.name, m.spec, m.unit, m.category, m.safety_stock
HAVING m.safety_stock IS NOT NULL AND COALESCE(SUM(s.qty), 0) < m.safety_stock
HAVING COALESCE(SUM(s.qty), 0) <> 0
ORDER BY m.code
